package com.repairconnect.entity;
import jakarta.persistence.*;
@Entity @Table(name="services") public class ServiceItem { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) private ProviderProfile provider; @ManyToOne(optional=false) private ServiceCategory category; private String serviceName; @Column(length=1000) private String description; private Double price; private Integer estimatedDuration; private boolean active=true; public ServiceItem(){} public ServiceItem(ProviderProfile p,ServiceCategory c,String n,Double price){provider=p;category=c;serviceName=n;this.price=price;} public Long getId(){return id;} public ProviderProfile getProvider(){return provider;} public ServiceCategory getCategory(){return category;} public String getServiceName(){return serviceName;} public String getDescription(){return description;} public Double getPrice(){return price;} public boolean isActive(){return active;} }